  "inlineSchema": "// HourBank - Community Skills-Swap Marketplace\n// To switch to PostgreSQL later: change provider to \"postgresql\" and update DATABASE_URL\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── NextAuth tables ───────────────────────────────────────────────\n\nmodel User {\n  id            String    @id @default(cuid())\n  name          String?\n  email         String    @unique\n  emailVerified DateTime?\n  image         String?\n  passwordHash  String?\n  bio           String?\n  location      String?\n  role          String    @default(\"USER\") // USER | ADMIN\n  creditBalance Float     @default(3) // Starter credits\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  accounts          Account[]\n  sessions          Session[]\n  userSkills        UserSkill[]\n  sentMessages      Message[]      @relation(\"SentMessages\")\n  receivedMessages  Message[]      @relation(\"ReceivedMessages\")\n  notifications     Notification[]\n  timeCredits       TimeCredit[]\n  requestedBookings Booking[]      @relation(\"RequestedBookings\")\n  providedBookings  Booking[]      @relation(\"ProvidedBookings\")\n  reviewsGiven      Review[]       @relation(\"ReviewsGiven\")\n  reviewsReceived   Review[]       @relation(\"ReviewsReceived\")\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n// ─── Skills ────────────────────────────────────────────────────────\n\nmodel Skill {\n  id          String  @id @default(cuid())\n  name        String\n  slug        String  @unique\n  category    String\n  description String?\n  icon        String?\n\n  userSkills UserSkill[]\n  bookings   Booking[]\n}\n\nmodel UserSkill {\n  id          String  @id @default(cuid())\n  userId      String\n  skillId     String\n  proficiency String  @default(\"INTERMEDIATE\") // BEGINNER | INTERMEDIATE | ADVANCED | EXPERT\n  isOffered   Boolean @default(true) // true = user offers this skill; false = user wants this\n  note        String?\n\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  skill Skill @relation(fields: [skillId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, skillId, isOffered])\n}\n\n// ─── Bookings ──────────────────────────────────────────────────────\n\nmodel Booking {\n  id              String    @id @default(cuid())\n  requesterId     String\n  providerId      String\n  skillId         String\n  status          String    @default(\"PENDING\") // PENDING | ACCEPTED | IN_PROGRESS | COMPLETED | CANCELLED | DISPUTED\n  description     String?\n  scheduledAt     DateTime?\n  durationMinutes Int       @default(60)\n  location        String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  requester   User         @relation(\"RequestedBookings\", fields: [requesterId], references: [id])\n  provider    User         @relation(\"ProvidedBookings\", fields: [providerId], references: [id])\n  skill       Skill        @relation(fields: [skillId], references: [id])\n  reviews     Review[]\n  timeCredits TimeCredit[]\n}\n\n// ─── Reviews ───────────────────────────────────────────────────────\n\nmodel Review {\n  id         String   @id @default(cuid())\n  bookingId  String\n  authorId   String\n  revieweeId String\n  rating     Int // 1-5\n  comment    String?\n  createdAt  DateTime @default(now())\n\n  booking  Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  author   User    @relation(\"ReviewsGiven\", fields: [authorId], references: [id])\n  reviewee User    @relation(\"ReviewsReceived\", fields: [revieweeId], references: [id])\n\n  @@unique([bookingId, authorId])\n}\n\n// ─── Time Credits ──────────────────────────────────────────────────\n\nmodel TimeCredit {\n  id               String   @id @default(cuid())\n  userId           String\n  amount           Float // positive = earned, negative = spent\n  type             String // INITIAL | EARNED | SPENT | ADJUSTED\n  description      String?\n  relatedBookingId String?\n  createdAt        DateTime @default(now())\n\n  user    User     @relation(fields: [userId], references: [id])\n  booking Booking? @relation(fields: [relatedBookingId], references: [id])\n}\n\n// ─── Messaging ─────────────────────────────────────────────────────\n\nmodel Message {\n  id         String   @id @default(cuid())\n  senderId   String\n  receiverId String\n  content    String\n  read       Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  sender   User @relation(\"SentMessages\", fields: [senderId], references: [id])\n  receiver User @relation(\"ReceivedMessages\", fields: [receiverId], references: [id])\n}\n\n// ─── Notifications ─────────────────────────────────────────────────\n\nmodel Notification {\n  id        String   @id @default(cuid())\n  userId    String\n  type      String // BOOKING_REQUEST | BOOKING_ACCEPTED | BOOKING_DECLINED | BOOKING_COMPLETED | REVIEW_RECEIVED | MESSAGE_RECEIVED | CREDIT_EARNED\n  title     String\n  body      String?\n  read      Boolean  @default(false)\n  link      String?\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n",
